algorithm MainDiagonal
    dimension data[3, 3] as integer;
    define row as integer;
    define col as integer;
    define total as integer;
    for row <- 0 to 2 step 1 do
        for col <- 0 to 2 step 1 do
            read data[row, col];
        endFor
    endFor
    total <- 0;
    for row <- 0 to 2 step 1 do
        for col <- 0 to 2 step 1 do
            total <- total + data[row, col];
        endFor
    endFor
    write total;
endAlgorithm
